set-variable.value:
@{
    var token = (Jwt)context.Variables["parsedJwt"];
    if (token.Issuer != "{{caller-okta-issuer}}" || token.Audiences.Count() != 1
        || token.Audiences.First() != "{{caller-okta-audience}}" || !token.ExpirationTime.HasValue
        || token.ExpirationTime.Value <= context.Timestamp
        || (token.NotBefore.HasValue && token.NotBefore.Value > context.Timestamp)) { return false; }
    var claims = token.Claims;
    foreach (var name in new[] { "sub", "uid", "cid" }) {
      if (!claims.ContainsKey(name) || claims[name] == null || claims[name].Length != 1
          || string.IsNullOrWhiteSpace(claims[name][0])) { return false; }
    }
    if (claims["sub"][0] != claims["uid"][0] || token.Subject != claims["sub"][0]
      || claims["cid"][0] == "{{caller-okta-audience}}"
        || !claims.ContainsKey("scp") || claims["scp"] == null
        || !claims["scp"].Contains("{{caller-okta-required-scope}}")) { return false; }
    var clients = "{{caller-okta-client-ids}}";
    return clients != "__none__" && clients.Split(',').Any(allowed => allowed.Trim() == claims["cid"][0]);
  }
